+      box-shadow: var(--shadow);
+      padding: 32px;
+      backdrop-filter: blur(18px);
+    }
+
+    h1 {
+      margin: 0 0 8px;
+      font-size: clamp(1.55rem, 3vw, 2rem);
+      line-height: 1.15;
+      letter-spacing: -0.02em;
+    }
+
+    .intro {
+      margin: 0 0 24px;
+      color: var(--muted);
+      line-height: 1.55;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      margin-bottom: 20px;
+    }
+
+    .checkbox-row {
+      display: grid;
+      grid-template-columns: 1.1rem 1fr;
+      gap: 12px;
+      align-items: start;
+    }
+
+    input[type="checkbox"] {
+      width: 1.1rem;
+      height: 1.1rem;
+      margin: 0;
+      accent-color: var(--accent-strong);
+      transform: translateY(0.2rem);
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.4;
+      cursor: pointer;
+    }
+
+    .required {
+      color: var(--accent);
+      font-weight: 700;
+    }
+
+    .help-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.96rem;
+      line-height: 1.5;
+    }
+
+    .error-text {
+      margin: 0;
+      color: var(--error);
+      font-size: 0.96rem;
+      line-height: 1.5;
+      background: var(--error-bg);
+      border: 1px solid rgba(251, 113, 133, 0.32);
+      border-radius: 12px;
+      padding: 10px 12px;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 14px;
+      padding: 0.95rem 1.25rem;
+      width: 100%;
+      font: inherit;
+      font-weight: 700;
