+      box-shadow: 0 14px 30px rgba(56, 189, 248, 0.28);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.03);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 3px solid #f8fafc;
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5em;
+      margin: 18px 0 0;
+      color: var(--success);
+      font-weight: 600;
+    }
+
+    [hidden] {
+      display: none !important;
+    }
+  </style>
+</head>
