+              id="agree-terms"
+              name="agreeTerms"
+              type="checkbox"
+              required
+              aria-describedby="agree-help agree-error"
+            >
+            <div>
+              <label for="agree-terms">
+                I agree to the Terms of Use <span class="required" aria-hidden="true">*</span>
+              </label>
+            </div>
+          </div>
+
+          <p id="agree-help" class="help-text">You must agree before submitting this form.</p>
+          <p id="agree-error" class="error-text" hidden>Error: Please agree to the Terms of Use.</p>
+        </div>
+
+        <button type="submit">Continue</button>
+        <p id="form-status" class="status" role="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
