     <section class="card" aria-labelledby="consent-title">
       <h1 id="consent-title">Terms of Use consent</h1>
       <p class="intro">Please confirm that you agree before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="agree-terms"
               name="agreeTerms"
               type="checkbox"
               required
               aria-describedby="agree-help agree-error"
             >
