     form.addEventListener('submit', (event) => {
       event.preventDefault();

       if (!checkbox.checked) {
         setError(true);
         statusText.textContent = 'Please agree to the Terms of Use to continue.';
         checkbox.focus();
         return;
       }

       setError(false);
       statusText.textContent = 'Consent recorded.';
